Object.assign(messages.ru, ruGaps);
Object.assign(messages.uz_cyrl, uzCyrlGaps);
messages.zh = { ...zhMessages };

// Har til: uz asos + o‘z tarjimasi — bo‘sh kalit qolmasin, 4 til bir xil yuzani beradi
for (const code of ['ru', 'uz_cyrl', 'zh']) {
    messages[code] = { ...messages.uz, ...(messages[code] || {}) };
}

export const i18nState = reactive({
    locale: localStorage.getItem('locale') || 'uz',
});

export const languages = [
    { code: 'uz', label: 'O‘zbek' },
    { code: 'uz_cyrl', label: 'Ўзбек' },
    { code: 'ru', label: 'Русский' },
    { code: 'zh', label: '中文' },
];

export function t(key, params = {}) {
    // locale o‘qilishi — template $t chaqiriqlari reaktiv bo‘lishi uchun
    const locale = i18nState.locale;
    const pack = messages[locale] || messages.uz;
    let text = pack[key] ?? messages.uz[key] ?? key;
    Object.entries(params || {}).forEach(([name, value]) => {
        text = String(text).replaceAll(`{${name}}`, String(value));
    });
    return text;
}

export function localeTag(locale = i18nState.locale) {
    if (locale === 'ru') return 'ru-RU';
    if (locale === 'zh') return 'zh-CN';
    if (locale === 'uz_cyrl') return 'uz-Cyrl-UZ';
    return 'uz-UZ';
}

export function setLocale(locale) {
    if (!messages[locale]) return;
    i18nState.locale = locale;
    localStorage.setItem('locale', locale);
    document.documentElement.lang = locale === 'ru' ? 'ru' : locale === 'zh' ? 'zh' : locale === 'uz_cyrl' ? 'uz-Cyrl' : 'uz';
    if (window.axios) {
        window.axios.defaults.headers.common['X-Locale'] = locale;
    }
}

setLocale(i18nState.locale);
